<?php
/** Wuxiaworld-style title detail with local content and existing reader actions. */
if (!defined('ABSPATH')) { exit; }
get_header();
while (have_posts()) : the_post();
$xv_id=get_the_ID();
$xv_rating=xv_rating($xv_id);
$xv_status=xv_novel_status($xv_id);
$xv_chapters=xv_novel_chapters($xv_id);
$xv_translator=get_post_meta($xv_id,'_xin_translator',true);
$xv_last=(int)get_post_meta($xv_id,'_xin_last_chapter_at',true);
?>
<article class="xv-title-page xv-world-title">
<div class="xv-book-feature"><div class="xv-book-layout"><div class="xv-book-visual"><span class="xv-novel-cover"><?php if(xv_cover_url($xv_id,'xv-cover-lg')) : ?><img src="<?php echo esc_url(xv_cover_url($xv_id,'xv-cover-lg')); ?>" alt="<?php echo esc_attr(get_the_title()); ?>" fetchpriority="high"><?php endif; ?></span></div>
<div class="xv-book-info"><span class="xv-world-title-status"><?php echo esc_html($xv_status?$xv_status->name:__('Веб-новелла','xin-v2')); ?></span><h1 class="xv-novel-title"><?php the_title(); ?></h1><div class="xv-world-title-rating"><span class="xv-world-rating"><b><?php echo esc_html(number_format_i18n($xv_rating['value'],1)); ?></b><?php echo xv_stars($xv_rating['value']); ?></span><a href="#comments"><?php echo esc_html(xv_counted($xv_rating['count'],xv_label_ratings($xv_rating['count']))); ?> ›</a></div>
<p class="xv-world-title-credit"><?php esc_html_e('Автор:','xin-v2'); ?> <a href="<?php echo esc_url(get_author_posts_url((int)get_post_field('post_author',$xv_id))); ?>"><?php echo esc_html(xv_novel_author($xv_id)); ?></a></p><?php if($xv_translator) : ?><p class="xv-world-title-credit"><?php esc_html_e('Переводчик:','xin-v2'); ?> <?php echo esc_html($xv_translator); ?></p><?php endif; ?>
<?php get_template_part('template-parts/book','rating'); ?>
<div class="xv-world-title-read"><div class="xv-world-release"><?php xv_the_icon('clock'); ?><span><?php echo esc_html(xv_counted(count($xv_chapters),xv_label_chapters(count($xv_chapters)))); ?></span><?php if($xv_last) : ?><time><?php echo esc_html(xv_ago($xv_last)); ?></time><?php endif; ?></div><div class="xv-novel-actions"><?php if($xv_chapters) : $xv_resume=xv_resume_chapter($xv_id,$xv_chapters); ?><a class="xv-btn primary xv-world-start" href="<?php echo esc_url(get_permalink($xv_resume['chapter'])); ?>"><?php echo esc_html($xv_resume['label']); ?></a><?php endif; ?><?php echo xv_fav_button($xv_id); ?><?php if(function_exists('xv_push_render_bell_button'))xv_push_render_bell_button($xv_id); ?><?php if(current_user_can('edit_post',$xv_id)) : ?><a class="xv-btn sm" href="<?php echo esc_url(xv_author_url(array('work'=>$xv_id,'view'=>'novel'))); ?>"><?php xv_the_icon('pen'); ?><?php esc_html_e('Редактировать','xin-v2'); ?></a><?php endif; ?></div></div>
</div></div></div>
<nav class="xv-book-jump" aria-label="<?php esc_attr_e('На странице книги','xin-v2'); ?>"><a href="#xv-book-description"><?php esc_html_e('О произведении','xin-v2'); ?></a><a href="#xv-book-chapters"><?php esc_html_e('Главы','xin-v2'); ?></a><?php if(xv_discussion_open($xv_id)||get_comments_number()) : ?><a href="#comments"><?php esc_html_e('Отзывы','xin-v2'); ?></a><?php endif; ?></nav>
<div class="xv-novel-body"><section class="xv-book-overview" id="xv-book-description" data-xv-book-panel="overview"><div class="xv-book-meta-panel"><dl class="xv-world-book-facts"><div><dt><?php esc_html_e('Главы','xin-v2'); ?></dt><dd><?php echo esc_html(number_format_i18n(count($xv_chapters))); ?></dd></div><div><dt><?php esc_html_e('Просмотры','xin-v2'); ?></dt><dd><?php echo esc_html(number_format_i18n(xv_get_views($xv_id))); ?></dd></div><?php $xv_year=get_post_meta($xv_id,'_xin_year',true); if($xv_year) : ?><div><dt><?php esc_html_e('Год','xin-v2'); ?></dt><dd><?php echo esc_html($xv_year); ?></dd></div><?php endif; ?></dl><div class="xv-novel-tags"><?php echo xv_genre_chips($xv_id,10,true); ?></div></div><div class="xv-world-synopsis"><h2><?php esc_html_e('Описание','xin-v2'); ?></h2><div class="xv-prose"><?php the_content(); ?></div></div><?php if(xv_can_download($xv_id)&&$xv_chapters) : ?><div class="xv-world-downloads"><h2><?php esc_html_e('Скачать книгу','xin-v2'); ?></h2><a class="xv-btn" rel="nofollow" href="<?php echo esc_url(xv_export_url($xv_id,'epub')); ?>">EPUB</a><a class="xv-btn" rel="nofollow" href="<?php echo esc_url(xv_export_url($xv_id,'fb2')); ?>">FB2</a></div><?php endif; ?></section>
<section id="xv-book-chapters" data-xv-book-panel="chapters" hidden><div class="xv-toc-head"><h2><?php esc_html_e('Главы','xin-v2'); ?> <span class="xv-episode-count"><?php echo esc_html(number_format_i18n(count($xv_chapters))); ?></span></h2><label class="xv-search xv-toc-search"><?php xv_the_icon('search'); ?><input type="search" data-xv-toc-search placeholder="<?php esc_attr_e('Поиск по главам','xin-v2'); ?>" aria-label="<?php esc_attr_e('Поиск по главам','xin-v2'); ?>"></label></div><div class="xv-toc" data-xv-toc><?php if($xv_chapters) : foreach($xv_chapters as $xv_i=>$xv_chapter)xv_toc_row($xv_chapter,$xv_i+1); else : ?><p class="xv-toc-empty"><?php esc_html_e('Глав пока нет.','xin-v2'); ?></p><?php endif; ?></div><?php if(xv_discussion_open($xv_id)||get_comments_number()) : ?><div class="xv-novel-comments"><?php comments_template(); ?></div><?php endif; ?></section></div>
<?php $xv_related=xv_similar_novels($xv_id,5); if($xv_related) : ?><section class="xv-world-related"><div class="xv-section-head"><h2><?php esc_html_e('Похожие произведения','xin-v2'); ?></h2></div><div class="xv-card-row xv-home-cards"><?php foreach($xv_related as $xv_novel)xv_novel_card($xv_novel->ID); ?></div></section><?php endif; ?>
</article>
<?php endwhile; get_footer(); ?>
